static class Pod {
    private final Map<String, Integer> counts = new HashMap<>();   // bộ đếm của từng pod
    boolean allow(String user) { return counts.merge(user, 1, Integer::sum) <= 100; }
}

public static void main(String[] args) {
    List<Pod> pods = List.of(new Pod(), new Pod(), new Pod());
    int accepted = 0;
    for (int i = 0; i < 400; i++) {
        Pod pod = pods.get(i % pods.size());          // chia luân phiên
        if (pod.allow("user-42")) accepted++;
    }
    System.out.println("accepted=" + accepted);
}
